// Package runtime owns durable API and reconciler checkpoints.
package runtime

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

var (
	ErrConflict   = errors.New("runtime identity conflicts with existing content")
	ErrInProgress = errors.New("runtime request is still processing")
	ErrNotFound   = errors.New("runtime record not found")
	ErrStaleFence = errors.New("stale runtime fencing token")
	ErrTerminal   = errors.New("runtime job is terminal")
)

type Job struct {
	ID           string
	RunID        string
	TaskID       *string
	Attempt      uint32
	Stage        string
	State        string
	AvailableAt  time.Time
	ClaimOwner   *string
	ClaimExpires *time.Time
	FencingToken uint64
	RetryCount   uint32
	Result       *workflow.ArtifactRef
	Failure      *workflow.ArtifactRef
}

// StageStatus is the secret-safe operator view of one durable stage job.
type StageStatus struct {
	TaskID     *string               `json:"task_id,omitempty"`
	Attempt    uint32                `json:"attempt"`
	Stage      string                `json:"stage"`
	State      string                `json:"state"`
	RetryCount uint32                `json:"retry_count"`
	Failure    *workflow.ArtifactRef `json:"failure,omitempty"`
}

type IdempotencyRequest struct {
	Key, Method, Target, PrincipalID, RequestDigest string
}

type IdempotencyResult struct {
	StatusCode   int
	Response     json.RawMessage
	Replay       bool
	FencingToken uint64
}

type idempotencyReservation struct {
	method, target, principal, digest string
	status                            *int
	response                          []byte
	reservedUntil                     time.Time
	fencingToken                      uint64
}

type Ledger struct{ pool *pgxpool.Pool }

func NewLedger(pool *pgxpool.Pool) *Ledger { return &Ledger{pool: pool} }

func Digest(body []byte) string {
	sum := sha256.Sum256(body)
	return hex.EncodeToString(sum[:])
}

func (l *Ledger) BeginIdempotency(ctx context.Context, request IdempotencyRequest) (*IdempotencyResult, error) {
	if _, err := uuid.Parse(request.Key); err != nil {
		return nil, fmt.Errorf("%w: idempotency key", ErrConflict)
	}
	now := time.Now().UTC()
	tx, err := l.pool.Begin(ctx)
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	inserted, err := insertIdempotencyReservation(ctx, tx, request, now)
	if err != nil {
		return nil, err
	}
	if inserted {
		return commitIdempotencyResult(ctx, tx, &IdempotencyResult{FencingToken: 1})
	}
	reservation, err := loadIdempotencyReservation(ctx, tx, request.Key)
	if err != nil {
		return nil, err
	}
	if !reservation.matches(request) {
		return nil, ErrConflict
	}
	if reservation.status != nil {
		return commitIdempotencyResult(ctx, tx, &IdempotencyResult{
			StatusCode: *reservation.status, Response: reservation.response, Replay: true,
			FencingToken: reservation.fencingToken,
		})
	}
	if reservation.reservedUntil.After(now) {
		return nil, ErrInProgress
	}
	reservation.fencingToken++
	if err := reclaimIdempotencyReservation(ctx, tx, request.Key, reservation.fencingToken, now); err != nil {
		return nil, err
	}
	return commitIdempotencyResult(ctx, tx, &IdempotencyResult{
		FencingToken: reservation.fencingToken,
	})
}

func insertIdempotencyReservation(
	ctx context.Context, tx pgx.Tx, request IdempotencyRequest, now time.Time,
) (bool, error) {
	tag, err := tx.Exec(ctx, `INSERT INTO runtime_api_idempotency
		(idempotency_key,method,target,principal_id,request_digest,
		 reservation_expires_at,reservation_generation)
		VALUES ($1,$2,$3,$4,$5,$6,1) ON CONFLICT DO NOTHING`,
		request.Key, request.Method, request.Target, request.PrincipalID,
		request.RequestDigest, now.Add(30*time.Second))
	if err != nil {
		return false, err
	}
	return tag.RowsAffected() == 1, nil
}

func loadIdempotencyReservation(
	ctx context.Context, tx pgx.Tx, key string,
) (idempotencyReservation, error) {
	var reservation idempotencyReservation
	err := tx.QueryRow(ctx, `SELECT method,target,principal_id::text,request_digest,
		status_code,response,reservation_expires_at,reservation_generation
		FROM runtime_api_idempotency
		WHERE idempotency_key=$1 FOR UPDATE`, key).Scan(
		&reservation.method, &reservation.target, &reservation.principal,
		&reservation.digest, &reservation.status, &reservation.response,
		&reservation.reservedUntil, &reservation.fencingToken)
	return reservation, err
}

func (r idempotencyReservation) matches(request IdempotencyRequest) bool {
	return r.method == request.Method && r.target == request.Target &&
		r.principal == request.PrincipalID && r.digest == request.RequestDigest
}

func reclaimIdempotencyReservation(
	ctx context.Context, tx pgx.Tx, key string, fencingToken uint64, now time.Time,
) error {
	_, err := tx.Exec(ctx, `UPDATE runtime_api_idempotency
		SET reservation_expires_at=$2,reservation_generation=$3
		WHERE idempotency_key=$1`,
		key, now.Add(30*time.Second), fencingToken)
	return err
}

func commitIdempotencyResult(
	ctx context.Context, tx pgx.Tx, result *IdempotencyResult,
) (*IdempotencyResult, error) {
	if err := tx.Commit(ctx); err != nil {
		return nil, err
	}
	return result, nil
}

func (l *Ledger) CompleteIdempotency(
	ctx context.Context, key string, fencingToken uint64, status int, response json.RawMessage,
) error {
	tag, err := l.pool.Exec(ctx, `UPDATE runtime_api_idempotency
		SET status_code=$3,response=$4,completed_at=now()
		WHERE idempotency_key=$1 AND reservation_generation=$2
		  AND completed_at IS NULL`, key, fencingToken, status, response)
	if err != nil {
		return err
	}
	if tag.RowsAffected() != 1 {
		var completedAt *time.Time
		err := l.pool.QueryRow(ctx, `SELECT completed_at FROM runtime_api_idempotency
			WHERE idempotency_key=$1`, key).Scan(&completedAt)
		switch {
		case errors.Is(err, pgx.ErrNoRows):
			return ErrNotFound
		case err != nil:
			return err
		case completedAt != nil:
			return ErrTerminal
		default:
			return ErrConflict
		}
	}
	return nil
}

func (l *Ledger) AbandonIdempotency(
	ctx context.Context, key string, fencingToken uint64,
) error {
	tag, err := l.pool.Exec(ctx, `UPDATE runtime_api_idempotency
		SET reservation_expires_at=clock_timestamp()
		WHERE idempotency_key=$1 AND reservation_generation=$2
		  AND completed_at IS NULL`, key, fencingToken)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 1 {
		return nil
	}
	var generation uint64
	var completedAt *time.Time
	err = l.pool.QueryRow(ctx, `SELECT reservation_generation,completed_at
		FROM runtime_api_idempotency WHERE idempotency_key=$1`, key).
		Scan(&generation, &completedAt)
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		return ErrNotFound
	case err != nil:
		return err
	case completedAt != nil:
		return ErrTerminal
	case generation != fencingToken:
		return ErrConflict
	default:
		return ErrConflict
	}
}

func (l *Ledger) Enqueue(ctx context.Context, job Job) error {
	var task any
	if job.TaskID != nil {
		task = *job.TaskID
	}
	tag, err := l.pool.Exec(ctx, `INSERT INTO runtime_stage_jobs
		(job_id,run_id,task_id,attempt,stage,state,available_at,created_at,updated_at)
		VALUES ($1,$2,$3,$4,$5,'READY',$6,$6,$6) ON CONFLICT DO NOTHING`,
		job.ID, job.RunID, task, job.Attempt, job.Stage, job.AvailableAt.UTC())
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 1 {
		return nil
	}
	var id string
	err = l.pool.QueryRow(ctx, `SELECT job_id::text FROM runtime_stage_jobs
		WHERE run_id=$1 AND task_id IS NOT DISTINCT FROM $2 AND attempt=$3 AND stage=$4`,
		job.RunID, task, job.Attempt, job.Stage).Scan(&id)
	if err != nil {
		return err
	}
	if id != job.ID {
		return ErrConflict
	}
	return nil
}

func (l *Ledger) RunStages(ctx context.Context, runID string) ([]StageStatus, error) {
	rows, err := l.pool.Query(ctx, `SELECT task_id::text,attempt,stage,state,retry_count,
		failure_uri,failure_digest FROM runtime_stage_jobs WHERE run_id=$1
		ORDER BY created_at,job_id`, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	result := make([]StageStatus, 0)
	for rows.Next() {
		var value StageStatus
		var failureURI, failureDigest *string
		if err := rows.Scan(&value.TaskID, &value.Attempt, &value.Stage, &value.State,
			&value.RetryCount, &failureURI, &failureDigest); err != nil {
			return nil, err
		}
		if failureURI != nil && failureDigest != nil {
			value.Failure = &workflow.ArtifactRef{URI: *failureURI, Digest: *failureDigest}
		}
		result = append(result, value)
	}
	return result, rows.Err()
}

func (l *Ledger) Claim(ctx context.Context, owner string, now time.Time, ttl time.Duration) (Job, bool, error) {
	tx, err := l.pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.ReadCommitted})
	if err != nil {
		return Job{}, false, err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	var job Job
	var taskID, claimOwner, resultURI, resultDigest, failureURI, failureDigest *string
	var claimExpires *time.Time
	err = tx.QueryRow(ctx, `SELECT job_id::text,run_id::text,task_id::text,attempt,stage,
		state,available_at,claim_owner::text,claim_expires_at,fencing_token,retry_count,
		result_uri,result_digest,failure_uri,failure_digest
		FROM runtime_stage_jobs
		WHERE state IN ('READY','RETRY','CLAIMED') AND available_at <= $1
		  AND (state <> 'CLAIMED' OR claim_expires_at <= $1)
		ORDER BY available_at,job_id FOR UPDATE SKIP LOCKED LIMIT 1`, now.UTC()).Scan(
		&job.ID, &job.RunID, &taskID, &job.Attempt, &job.Stage, &job.State,
		&job.AvailableAt, &claimOwner, &claimExpires, &job.FencingToken,
		&job.RetryCount, &resultURI, &resultDigest, &failureURI, &failureDigest)
	if errors.Is(err, pgx.ErrNoRows) {
		return Job{}, false, nil
	}
	if err != nil {
		return Job{}, false, err
	}
	job.TaskID = taskID
	if resultURI != nil && resultDigest != nil {
		job.Result = &workflow.ArtifactRef{URI: *resultURI, Digest: *resultDigest}
	}
	if failureURI != nil && failureDigest != nil {
		job.Failure = &workflow.ArtifactRef{URI: *failureURI, Digest: *failureDigest}
	}
	expires := now.UTC().Add(ttl)
	job.FencingToken++
	tag, err := tx.Exec(ctx, `UPDATE runtime_stage_jobs SET state='CLAIMED',
		claim_owner=$2,claim_expires_at=$3,fencing_token=$4,updated_at=$5 WHERE job_id=$1`,
		job.ID, owner, expires, job.FencingToken, now.UTC())
	if err != nil || tag.RowsAffected() != 1 {
		return Job{}, false, err
	}
	if err := tx.Commit(ctx); err != nil {
		return Job{}, false, err
	}
	job.State, job.ClaimOwner, job.ClaimExpires = "CLAIMED", &owner, &expires
	return job, true, nil
}

func (l *Ledger) Complete(
	ctx context.Context, jobID, owner string, fence uint64, result workflow.ArtifactRef, now time.Time,
) error {
	if err := result.Validate(); err != nil {
		return err
	}
	tag, err := l.pool.Exec(ctx, `UPDATE runtime_stage_jobs SET state='COMPLETED',
		result_uri=$4,result_digest=$5,claim_owner=NULL,claim_expires_at=NULL,updated_at=$6
		WHERE job_id=$1 AND state='CLAIMED' AND claim_owner=$2 AND fencing_token=$3`,
		jobID, owner, fence, result.URI, result.Digest, now.UTC())
	if err != nil {
		return err
	}
	if tag.RowsAffected() != 1 {
		return l.classifyJobUpdate(ctx, jobID)
	}
	return nil
}

func (l *Ledger) Renew(
	ctx context.Context, jobID, owner string, fence uint64, expires time.Time,
) error {
	tag, err := l.pool.Exec(ctx, `UPDATE runtime_stage_jobs
		SET claim_expires_at=$4,updated_at=now()
		WHERE job_id=$1 AND state='CLAIMED' AND claim_owner=$2 AND fencing_token=$3`,
		jobID, owner, fence, expires.UTC())
package controlapi

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"path/filepath"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/beta"
	"github.com/Standard-Syntax/basic/go/internal/runtime"
	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

type RunIntakeRequest struct {
	Idempotency runtime.IdempotencyRequest
	Command     workflow.CreateRun
	Content     json.RawMessage
	BaseCommit  string
}

type RunIntake interface {
	Accept(context.Context, RunIntakeRequest) (*runtime.IdempotencyResult, error)
}

type transactionalWorkflow interface {
	ExecuteRunTx(context.Context, pgx.Tx, workflow.RunCommand) (workflow.CommandResult, error)
}

type IntakeFaultPoint string

const (
	FaultAfterReservation   IntakeFaultPoint = "after_reservation"
	FaultAfterIntakeCAS     IntakeFaultPoint = "after_intake_cas"
	FaultAfterRepositoryCAS IntakeFaultPoint = "after_repository_cas"
	FaultAfterPolicyCAS     IntakeFaultPoint = "after_policy_cas"
	FaultAfterWorkflow      IntakeFaultPoint = "after_workflow"
	FaultAfterBinding       IntakeFaultPoint = "after_binding"
	FaultAfterResponse      IntakeFaultPoint = "after_response"
	FaultIntakeBeforeCommit IntakeFaultPoint = "before_commit"
	FaultIntakeAfterCommit  IntakeFaultPoint = "after_commit"
)

type RunIntakeCoordinator struct {
	pool           *pgxpool.Pool
	ledger         *runtime.Ledger
	workflow       transactionalWorkflow
	artifacts      ArtifactStore
	repositoryRoot string
	policy         beta.Policy
	inject         func(IntakeFaultPoint) error
}

const intakeCleanupTimeout = 5 * time.Second

type stagedRunIntake struct {
	intake        workflow.ArtifactRef
	repositoryMap workflow.ArtifactRef
	policy        workflow.ArtifactRef
}

func NewRunIntakeCoordinator(
	pool *pgxpool.Pool, store transactionalWorkflow, artifacts ArtifactStore,
	repositoryRoot string, configuredPolicy ...beta.Policy,
) (*RunIntakeCoordinator, error) {
	if pool == nil || store == nil || artifacts == nil {
		return nil, errors.New("run intake dependencies are required")
	}
	if !filepath.IsAbs(repositoryRoot) || filepath.Clean(repositoryRoot) != repositoryRoot {
		return nil, errors.New("repository root must be clean and absolute")
	}
	if len(configuredPolicy) != 1 || configuredPolicy[0].Repository.Root != repositoryRoot {
		return nil, errors.New("one matching beta policy is required")
	}
	if err := configuredPolicy[0].Validate(); err != nil {
		return nil, err
	}
	return &RunIntakeCoordinator{
		pool: pool, ledger: runtime.NewLedger(pool), workflow: store,
		artifacts: artifacts, repositoryRoot: repositoryRoot, policy: configuredPolicy[0],
	}, nil
}

func (c *RunIntakeCoordinator) fault(point IntakeFaultPoint) error {
	if c.inject != nil {
		return c.inject(point)
	}
	return nil
}

func (c *RunIntakeCoordinator) Accept(
	ctx context.Context, request RunIntakeRequest,
) (*runtime.IdempotencyResult, error) {
	if err := validateRunIntakeRequest(request); err != nil {
		return nil, err
	}
	reservation, err := c.ledger.BeginIdempotency(ctx, request.Idempotency)
	if err != nil || reservation.Replay {
		return reservation, err
	}
	fence := reservation.FencingToken
	if err := c.fault(FaultAfterReservation); err != nil {
		return nil, c.abandonReservation(ctx, request.Idempotency.Key, fence, err)
	}
	staged, err := c.stageArtifacts(ctx, request)
	if err != nil {
		return nil, c.abandonReservation(ctx, request.Idempotency.Key, fence, err)
	}
	response, commitAttempted, err := c.commitIntake(ctx, request, fence, staged)
	if err != nil {
		if commitAttempted {
			return nil, err
		}
		return nil, c.abandonReservation(ctx, request.Idempotency.Key, fence, err)
	}
	if err := c.fault(FaultIntakeAfterCommit); err != nil {
		return nil, err
	}
	return &runtime.IdempotencyResult{
		StatusCode: http.StatusCreated, Response: response, FencingToken: fence,
	}, nil
}

func validateRunIntakeRequest(request RunIntakeRequest) error {
	if request.Idempotency.Method != http.MethodPost || request.Idempotency.Target != "/v1/runs" ||
		request.Command.Meta.CommandID != request.Idempotency.Key ||
		request.Command.Meta.Actor.ID != request.Idempotency.PrincipalID ||
		request.Command.Meta.Actor.Kind != workflow.ActorHuman ||
		request.Command.Meta.ExpectedRevision != 0 {
		return runtime.ErrConflict
	}
	return request.Command.Meta.Validate()
}

func (c *RunIntakeCoordinator) stageArtifacts(
	ctx context.Context, request RunIntakeRequest,
) (stagedRunIntake, error) {
	if request.BaseCommit != c.policy.Repository.BaseCommit {
		return stagedRunIntake{}, runtime.ErrConflict
	}
	if err := beta.VerifyRemoteBase(ctx, c.policy); err != nil {
		return stagedRunIntake{}, err
	}
	intake, err := c.artifacts.Put(ctx, request.Content)
	if err != nil {
		return stagedRunIntake{}, err
	}
	if err := c.fault(FaultAfterIntakeCAS); err != nil {
		return stagedRunIntake{}, err
	}
	snapshot, err := runtime.SnapshotRepository(ctx, c.repositoryRoot, request.BaseCommit)
	if err != nil {
		return stagedRunIntake{}, err
	}
	if snapshot.BaseCommit != request.BaseCommit {
		return stagedRunIntake{}, runtime.ErrConflict
	}
	repositoryBody, err := json.Marshal(snapshot)
	if err != nil {
		return stagedRunIntake{}, err
	}
	repositoryMap, err := c.artifacts.Put(ctx, repositoryBody)
	if err != nil {
		return stagedRunIntake{}, err
	}
	if err := c.fault(FaultAfterRepositoryCAS); err != nil {
		return stagedRunIntake{}, err
	}
	policyBody, _, err := c.policy.Canonical()
	if err != nil {
		return stagedRunIntake{}, err
	}
	policy, err := c.artifacts.Put(ctx, policyBody)
	if err != nil {
		return stagedRunIntake{}, err
	}
	if err := c.fault(FaultAfterPolicyCAS); err != nil {
		return stagedRunIntake{}, err
	}
	return stagedRunIntake{intake: intake, repositoryMap: repositoryMap, policy: policy}, nil
}

func (c *RunIntakeCoordinator) commitIntake(
	ctx context.Context, request RunIntakeRequest, fence uint64, staged stagedRunIntake,
) (response []byte, commitAttempted bool, err error) {
	tx, err := c.pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.Serializable})
	if err != nil {
		return nil, false, err
	}
	defer func() {
		err = rollbackIntake(ctx, tx, commitAttempted, err)
	}()
	if err := lockIntakeReservation(ctx, tx, request.Idempotency, fence); err != nil {
		return nil, false, err
	}
	result, err := c.workflow.ExecuteRunTx(ctx, tx, request.Command)
	if err != nil {
		return nil, false, err
	}
	if err := c.fault(FaultAfterWorkflow); err != nil {
		return nil, false, err
	}
	binding := runtime.RunBinding{
		RunID: request.Command.ID, Intake: staged.intake, BaseCommit: request.BaseCommit,
		RepositoryMap: &staged.repositoryMap, Policy: &staged.policy,
		ExecutionImageDigest:    c.policy.Images.Execution,
		VerificationImageDigest: c.policy.Images.Verification,
		CreatedAt:               request.Command.Meta.Timestamp,
	}
	if err := runtime.CreateRunBindingTx(ctx, tx, binding); err != nil {
		return nil, false, err
	}
	if err := c.fault(FaultAfterBinding); err != nil {
		return nil, false, err
	}
	response, err = json.Marshal(result)
	if err != nil {
		return nil, false, err
	}
	response, err = completeIntakeReservation(
		ctx, tx, request.Idempotency.Key, fence, http.StatusCreated, response,
	)
	if err != nil {
		return nil, false, err
	}
	if err := c.fault(FaultAfterResponse); err != nil {
		return nil, false, err
	}
	if err := c.fault(FaultIntakeBeforeCommit); err != nil {
		return nil, false, err
	}
	commitAttempted = true
	if err = tx.Commit(ctx); err != nil {
		// A commit error can be ambiguous. Leave the fenced reservation intact so
		// a retry either observes the committed response or reclaims after expiry.
		return nil, true, fmt.Errorf("commit run intake: %w", err)
	}
	return response, true, nil
}

func rollbackIntake(ctx context.Context, tx pgx.Tx, commitAttempted bool, cause error) error {
	if cause == nil || commitAttempted {
		return cause
	}
	cleanupCtx, cancel := detachedCleanupContext(ctx)
	defer cancel()
	rollbackErr := tx.Rollback(cleanupCtx)
	if rollbackErr != nil && !errors.Is(rollbackErr, pgx.ErrTxClosed) {
		return errors.Join(cause, rollbackErr)
	}
	return cause
}

