	}
	approvalResult, err := s.approval.ApproveTask(ctx, approval.Request{
		ApprovalID: stableStepID(key, "approve-task"), DecisionTimestamp: at,
		Principal: approval.Principal{ID: principal.ID, Roles: roles},
