const (
	FaultBeforeEvents   FaultPoint = "before_events"
	FaultBeforeSnapshot FaultPoint = "before_snapshot"
	FaultBeforeCommit   FaultPoint = "before_commit"
)

func NewStore(pool *pgxpool.Pool) *Store {
