		MaxBodyBytes:  512,
		TrustedChecks: []string{"make-check-v1"},
		Policy:        testPolicy("/tmp/repository", strings.Repeat("a", 40), "https://example.invalid/repository.git"),
	}, workflowStore, runtimeLedger, &fakeRunIntake{
