func readTreeEntry(
	ctx context.Context, repository, commit, filePath string,
) (treeEntry, error) {
	output, err := gitOutput(ctx, repository, "ls-tree", "-z", commit, "--", filePath)
	if err != nil {
		return treeEntry{}, err
	}
	record := bytes.TrimSuffix(output, []byte{0})
	header, actualPath, ok := bytes.Cut(record, []byte{'\t'})
	fields := bytes.Fields(header)
	if !ok || string(actualPath) != filePath || len(fields) != 3 ||
		string(fields[1]) != "blob" ||
		(string(fields[0]) != "100644" && string(fields[0]) != "100755") {
		return treeEntry{}, fmt.Errorf("%w: unsupported tree entry %q", ErrUnsafePath, filePath)
	}
	body, err := gitOutput(ctx, repository, "cat-file", "blob", string(fields[2]))
	if err != nil {
		return treeEntry{}, err
	}
	return treeEntry{mode: string(fields[0]), objectID: string(fields[2]), body: body}, nil
}

func gitIndexOutput(
	ctx context.Context,
	repository, index string,
	input []byte,
	arguments ...string,
) ([]byte, error) {
	return gitIndexOutputEnv(ctx, repository, index, input, nil, arguments...)
}

func gitIndexOutputEnv(
	ctx context.Context,
	repository, index string,
	input []byte,
	extraEnvironment []string,
	arguments ...string,
) ([]byte, error) {
	base := []string{
		"--literal-pathspecs",
		"-c", "core.hooksPath=/dev/null",
		"-c", "diff.external=",
		"-c", "core.attributesFile=/dev/null",
		"-C", repository,
	}
	command := exec.CommandContext(ctx, "git", append(base, arguments...)...)
	command.Env = append(os.Environ(),
		"GIT_CONFIG_NOSYSTEM=1",
		"GIT_CONFIG_GLOBAL=/dev/null",
		"GIT_OPTIONAL_LOCKS=0",
		"GIT_INDEX_FILE="+index,
	)
	command.Env = append(command.Env, extraEnvironment...)
	command.Stdin = bytes.NewReader(input)
	var stdout, stderr bytes.Buffer
	command.Stdout = &stdout
	command.Stderr = &stderr
	if err := command.Run(); err != nil {
		return nil, fmt.Errorf(
			"git %s: %w: %s", arguments[0], err, strings.TrimSpace(stderr.String()),
		)
	}
	return stdout.Bytes(), nil
}

func candidateRef(request contracts.ImplementationRequest, fence uint32) (string, error) {
	runID, taskID := request.Envelope.RunID, request.ApprovedTaskID
	if !refComponentPattern.MatchString(runID) || !refComponentPattern.MatchString(taskID) {
		return "", fmt.Errorf("%w: candidate ref identity", ErrInvalidRequest)
	}
	return "refs/harness/candidates/" + runID + "/" + taskID + "/" +
		strconv.FormatUint(uint64(request.Envelope.Attempt), 10) + "-" +
		strconv.FormatUint(uint64(fence), 10), nil
}

func deleteCandidateRef(
	ctx context.Context, repository, ref, candidate string,
) error {
	_, err := gitOutput(ctx, repository, "update-ref", "-d", ref, candidate)
	return err
}

func marshalReport(report ExecutionReport) ([]byte, error) {
	body, err := json.Marshal(report)
	if err != nil {
		return workflow.ArtifactRef{}, workflow.ArtifactRef{}, err
	}
	taskRef, err := store.Put(ctx, taskBody)
	if err != nil {
		return workflow.ArtifactRef{}, workflow.ArtifactRef{}, err
	}
	return graphRef, taskRef, nil
}

func SnapshotRepository(ctx context.Context, root, base string) (RepositorySnapshot, error) {
	if !filepath.IsAbs(root) || filepath.Clean(root) != root {
		return RepositorySnapshot{}, ErrScope
	}
	commitBody, err := gitOutput(ctx, root, "rev-parse", "--verify", base+"^{commit}")
	if err != nil {
		return RepositorySnapshot{}, fmt.Errorf("resolve base commit: %w", err)
	}
	commit := strings.TrimSpace(string(commitBody))
	if len(commit) != 40 {
		return RepositorySnapshot{}, ErrScope
	}
	tree, err := gitOutput(ctx, root, "ls-tree", "-rz", "--full-tree", commit)
	if err != nil {
		return RepositorySnapshot{}, err
	}
	var entries []*reasoningv1.RepositoryEntry
	for _, record := range bytes.Split(tree, []byte{0}) {
		if len(record) == 0 {
			continue
		}
		header, name, ok := bytes.Cut(record, []byte{'\t'})
		fields := bytes.Fields(header)
		if !ok || len(fields) != 3 || string(fields[1]) != "blob" || !safeRepoPath(string(name)) {
			return RepositorySnapshot{}, ErrScope
		}
		body, err := gitOutput(ctx, root, "cat-file", "blob", string(fields[2]))
		if err != nil {
			return RepositorySnapshot{}, err
		}
		sum := sha256.Sum256(body)
		entries = append(entries, &reasoningv1.RepositoryEntry{
			Path: string(name), Kind: "blob", Sha256: hex.EncodeToString(sum[:]),
		})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Path < entries[j].Path })
	snapshot := RepositorySnapshot{BaseCommit: commit, Entries: entries}
	if err := snapshot.Validate(commit); err != nil {
		return RepositorySnapshot{}, err
	}
	return snapshot, nil
}

func BuildImplementationContext(
	ctx context.Context,
	root, commit string,
	snapshot RepositorySnapshot,
	readable, _ []string,
	limits ContextLimits,
) ([]*reasoningv1.RepositoryContextFile, error) {
	if commit != snapshot.BaseCommit || limits.MaxFiles <= 0 || limits.MaxBytes <= 0 {
		return nil, ErrScope
	}
	var result []*reasoningv1.RepositoryContextFile
	var total int64
	for _, entry := range snapshot.Entries {
		if !withinAny(entry.Path, readable) {
			continue
		}
		if len(result) == limits.MaxFiles {
			return nil, ErrScopeLimit
		}
		body, err := gitOutput(ctx, root, "show", commit+":"+entry.Path)
		if err != nil {
			return nil, err
		}
		total += int64(len(body))
		if total > limits.MaxBytes {
			return nil, ErrScopeLimit
		}
		if Digest(body) != entry.Sha256 {
			return nil, ErrScope
		}
		result = append(result, &reasoningv1.RepositoryContextFile{
			Path: entry.Path, Sha256: entry.Sha256, Content: string(body),
		})
	}
	if len(result) == 0 {
		return nil, ErrScope
	}
	return result, nil
}

func gitOutput(ctx context.Context, root string, args ...string) ([]byte, error) {
	base := []string{"-C", root, "-c", "core.hooksPath=/dev/null", "-c", "diff.external=", "-c", "filter.lfs.smudge=", "-c", "filter.lfs.clean="}
	command := exec.CommandContext(ctx, "git", append(base, args...)...)
