	output, err := command.Output()
	if err != nil {
		return nil, err
	}
	return output, nil
}

func safeRepoPath(value string) bool {
	return value != "" && value == path.Clean(value) && !path.IsAbs(value) &&
		value != "." && value != ".git" && !strings.HasPrefix(value, "../") &&
		!strings.HasPrefix(value, ".git/")
}

func withinAny(value string, roots []string) bool {
	for _, root := range roots {
		root = strings.TrimSuffix(path.Clean(root), "/")
		if safeRepoPath(root) && (value == root || strings.HasPrefix(value, root+"/")) {
			return true
		}
	}
	return false
}
// Package repository provides hook- and filter-free access to Git objects.
package repository

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"strconv"
	"strings"
)

var (
	ErrInvalidCommit = errors.New("invalid git commit")
	ErrUnsafePath    = errors.New("unsafe repository path")
)

// MaterializeTree writes the tracked blobs in commit directly from Git's object
// database. It never invokes checkout, attributes, filters, hooks, textconv, or
// external diff drivers.
func MaterializeTree(ctx context.Context, repository, destination, commit string) error {
	objectType, err := gitOutput(ctx, repository, "cat-file", "-t", commit)
	if err != nil || strings.TrimSpace(string(objectType)) != "commit" {
		return ErrInvalidCommit
	}
	tree, err := gitOutput(ctx, repository, "ls-tree", "-rz", "--full-tree", "-r", commit)
	if err != nil {
		return fmt.Errorf("list tree: %w", err)
	}
	root, err := os.OpenRoot(destination)
	if err != nil {
		return fmt.Errorf("open materialization root: %w", err)
	}
	defer root.Close()
	for _, record := range bytes.Split(tree, []byte{0}) {
		if len(record) == 0 {
			continue
		}
		mode, objectID, name, err := parseTreeRecord(record)
		if err != nil {
			return err
		}
		if err := materializeEntry(ctx, repository, root, mode, objectID, name); err != nil {
			return err
		}
	}
	return nil
}

func parseTreeRecord(record []byte) (string, string, string, error) {
	header, pathBytes, ok := bytes.Cut(record, []byte{'\t'})
	fields := bytes.Fields(header)
	if !ok || len(fields) != 3 {
		return "", "", "", errors.New("invalid git tree record")
	}
	mode, objectType, objectID := string(fields[0]), string(fields[1]), string(fields[2])
	name := string(pathBytes)
	if !safePath(name) {
		return "", "", "", fmt.Errorf("%w: tracked path %q", ErrUnsafePath, name)
	}
	if objectType != "blob" || (mode != "100644" && mode != "100755" && mode != "120000") {
		return "", "", "", fmt.Errorf(
			"%w: unsupported tracked entry %q mode %s", ErrUnsafePath, name, mode,
		)
	}
	return mode, objectID, name, nil
}

func safePath(name string) bool {
	if name == "" || path.IsAbs(name) || path.Clean(name) != name ||
		strings.Contains(name, `\`) {
		return false
	}
	for _, component := range strings.Split(name, "/") {
		if component == "" || component == "." || component == ".." || component == ".git" {
			return false
		}
	}
	return true
}

func materializeEntry(
	ctx context.Context, repository string, root *os.Root, mode, objectID, name string,
) error {
	body, err := gitOutput(ctx, repository, "cat-file", "blob", objectID)
	if err != nil {
		return fmt.Errorf("read tracked blob %q: %w", name, err)
	}
	parent := filepath.ToSlash(filepath.Dir(name))
	if parent != "." {
		if err := root.MkdirAll(parent, 0o750); err != nil {
			return fmt.Errorf("create tracked parent %q: %w", parent, err)
		}
	}
	if mode == "120000" {
		if err := root.Symlink(string(body), name); err != nil {
			return fmt.Errorf("materialize symlink %q: %w", name, err)
		}
		return nil
	}
	permissions, _ := strconv.ParseUint(mode[3:], 8, 32)
	if err := root.WriteFile(name, body, os.FileMode(permissions)); err != nil {
		return fmt.Errorf("materialize blob %q: %w", name, err)
	}
	return nil
}

func gitOutput(ctx context.Context, repository string, arguments ...string) ([]byte, error) {
	base := []string{
		"--literal-pathspecs",
		"-c", "core.hooksPath=/dev/null",
		"-c", "diff.external=",
		"-c", "core.attributesFile=/dev/null",
		"-C", repository,
	}
	command := exec.CommandContext(ctx, "git", append(base, arguments...)...)
	command.Env = []string{
		"PATH=" + os.Getenv("PATH"),
		"GIT_CONFIG_NOSYSTEM=1",
		"GIT_CONFIG_GLOBAL=/dev/null",
		"GIT_OPTIONAL_LOCKS=0",
		"LANG=C",
	}
	var stdout, stderr bytes.Buffer
	command.Stdout = &stdout
	command.Stderr = &stderr
	if err := command.Run(); err != nil {
		return nil, fmt.Errorf(
			"git %s: %w: %s", arguments[0], err, strings.TrimSpace(stderr.String()),
		)
	}
	return stdout.Bytes(), nil
}
package publication

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"syscall"
)

var (
	commitPattern         = regexp.MustCompile(`^[a-f0-9]{40}$`)
	branchPattern         = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._/-]{0,199}$`)
	credentialPathPattern = regexp.MustCompile(`^/[A-Za-z0-9_./-]+$`)
)

type GitCommandPublisher struct {
	root       string
	remote     string
	baseBranch string
	sshKeyFile string
}

// NewAuthenticatedGitCommandPublisher binds Git pushes to one explicitly
// mounted owner-only SSH key. The legacy constructor remains for loopback and
// non-canary callers that provide authentication outside this process.
func NewAuthenticatedGitCommandPublisher(
	root, remote, baseBranch, sshKeyFile string,
) (*GitCommandPublisher, error) {
	publisher, err := NewGitCommandPublisher(root, remote, baseBranch)
	if err != nil {
		return nil, err
	}
	if !filepath.IsAbs(sshKeyFile) || filepath.Clean(sshKeyFile) != sshKeyFile ||
		!credentialPathPattern.MatchString(sshKeyFile) {
		return nil, ErrCredentialPermissions
	}
	info, err := os.Lstat(sshKeyFile)
	if err != nil || !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 ||
		info.Mode().Perm() != 0o600 {
		return nil, ErrCredentialPermissions
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != os.Geteuid() {
		return nil, ErrCredentialPermissions
	}
	publisher.sshKeyFile = sshKeyFile
	return publisher, nil
}

func NewGitCommandPublisher(root, remote, baseBranch string) (*GitCommandPublisher, error) {
	if strings.TrimSpace(root) == "" || !branchPattern.MatchString(remote) ||
		!branchPattern.MatchString(baseBranch) {
		return nil, fmt.Errorf("%w: git configuration", ErrInvalidRequest)
	}
	return &GitCommandPublisher{root: root, remote: remote, baseBranch: baseBranch}, nil
}

func (p *GitCommandPublisher) BaseHead(ctx context.Context) (string, error) {
	head, exists, err := p.remoteHead(ctx, p.baseBranch)
	if err != nil {
		return "", err
	}
	if !exists {
		return "", fmt.Errorf("%w: remote base branch is missing", ErrBaseDrift)
	}
	return head, nil
}

func (p *GitCommandPublisher) BranchHead(
	ctx context.Context, branch string,
) (string, bool, error) {
	if !branchPattern.MatchString(branch) {
		return "", false, fmt.Errorf("%w: branch name", ErrInvalidRequest)
	}
	return p.remoteHead(ctx, branch)
}

func (p *GitCommandPublisher) Publish(
	ctx context.Context, branch, candidate string,
) (bool, error) {
	if !branchPattern.MatchString(branch) || !commitPattern.MatchString(candidate) {
		return false, fmt.Errorf("%w: branch publication binding", ErrInvalidRequest)
	}
	if err := p.run(ctx, nil, "cat-file", "-e", candidate+"^{commit}"); err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return false, ctxErr
		}
		return false, fmt.Errorf("%w: candidate commit is unavailable: %v", ErrInvalidRequest, err)
	}
	head, exists, err := p.BranchHead(ctx, branch)
	if err != nil {
		return false, err
	}
	if exists {
		if head == candidate {
			return true, nil
		}
		return false, ErrBranchConflict
	}
	ref := "refs/heads/" + branch
	pushErr := p.run(ctx, nil, "push", "--porcelain", "--no-verify",
		"--force-with-lease="+ref+":", p.remote, candidate+":"+ref)
	if pushErr == nil {
		return false, nil
	}
	head, exists, inspectErr := p.BranchHead(ctx, branch)
	if inspectErr == nil && exists && head == candidate {
		return true, nil
	}
	if inspectErr == nil && exists {
		return false, ErrBranchConflict
	}
	return false, fmt.Errorf("publish candidate branch: %w", pushErr)
}

// DeleteBranch removes only the exact branch if its remote head still equals
// candidate. A missing branch is an idempotent success.
func (p *GitCommandPublisher) DeleteBranch(
	ctx context.Context, branch, candidate string,
) (bool, error) {
	if !branchPattern.MatchString(branch) || !commitPattern.MatchString(candidate) {
		return false, fmt.Errorf("%w: branch cleanup binding", ErrInvalidRequest)
	}
	head, exists, err := p.BranchHead(ctx, branch)
	if err != nil {
		return false, err
	}
	if !exists {
		return true, nil
	}
	if head != candidate {
		return false, ErrBranchConflict
	}
	ref := "refs/heads/" + branch
	deleteErr := p.run(ctx, nil, "push", "--porcelain", "--no-verify",
		"--force-with-lease="+ref+":"+candidate, p.remote, ":"+ref)
	if deleteErr == nil {
		return false, nil
	}
	head, exists, inspectErr := p.BranchHead(ctx, branch)
	if inspectErr == nil && !exists {
		return true, nil
	}
	if inspectErr == nil && head != candidate {
		return false, ErrBranchConflict
	}
	return false, fmt.Errorf("delete publication branch: %w", deleteErr)
}

func (p *GitCommandPublisher) remoteHead(
	ctx context.Context, branch string,
) (string, bool, error) {
	var output bytes.Buffer
	err := p.run(ctx, &output, "ls-remote", "--heads", p.remote, "refs/heads/"+branch)
	if err != nil {
		return "", false, fmt.Errorf("inspect remote branch: %w", err)
	}
	fields := strings.Fields(output.String())
	if len(fields) == 0 {
		return "", false, nil
	}
	if len(fields) != 2 || !commitPattern.MatchString(fields[0]) {
		return "", false, errors.New("invalid git ls-remote response")
	}
	return fields[0], true, nil
}

func (p *GitCommandPublisher) run(
	ctx context.Context, stdout *bytes.Buffer, args ...string,
) error {
	command := exec.CommandContext(ctx, "git", args...)
	command.Dir = p.root
	command.Env = append(os.Environ(),
		"GIT_TERMINAL_PROMPT=0",
		"GIT_ASKPASS=",
		"SSH_ASKPASS=",
		"GIT_CONFIG_COUNT=2",
		"GIT_CONFIG_KEY_0=core.hooksPath",
		"GIT_CONFIG_VALUE_0=/dev/null",
		"GIT_CONFIG_KEY_1=credential.interactive",
		"GIT_CONFIG_VALUE_1=never",
	)
