		return nil, fmt.Errorf("%w: GitHub client configuration", ErrInvalidRequest)
	}
	return &GitHubRESTClient{
		endpoint: parsed, apiVersion: apiVersion, maxBodyBytes: maxBodyBytes,
		credentials: credentials,
